import{_ as l,r as t,o as i,c as u,e as p,a as n,s as e,d as a}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Создание полей Tailor - October CMS - 3.x","titleTemplate":false,"description":"Расширение Tailor пользовательскими контентными полями.","frontmatter":{"subtitle":"Расширение Tailor пользовательскими контентными полями."},"headers":[{"level":3,"title":"Определение класса","slug":"определение-класса","link":"#определение-класса","children":[]},{"level":3,"title":"Регистрация контентного поля","slug":"регистрация-контентного-поля","link":"#регистрация-контентного-поля","children":[]},{"level":2,"title":"Обработка конфигурации","slug":"обработка-конфигурации","link":"#обработка-конфигурации","children":[]},{"level":2,"title":"Определение элемента панели управления","slug":"определение-элемента-панели-управления","link":"#определение-элемента-панели-управления","children":[{"level":3,"title":"Поле формы","slug":"поле-формы","link":"#поле-формы","children":[]},{"level":3,"title":"Столбец списка","slug":"столбец-списка","link":"#столбец-списка","children":[]},{"level":3,"title":"Область фильтрации","slug":"область-фильтрации","link":"#область-фильтрации","children":[]}]},{"level":2,"title":"Расширение модели","slug":"расширение-модели","link":"#расширение-модели","children":[]},{"level":2,"title":"Расширение таблицы базы данных","slug":"расширение-таблицы-базы-данных","link":"#расширение-таблицы-базы-данных","children":[]},{"level":2,"title":"Полный пример использования","slug":"полныи-пример-использования","link":"#полныи-пример-использования","children":[]},{"level":2,"title":"Виджеты форм и контентные поля","slug":"виджеты-форм-и-контентные-поля","link":"#виджеты-форм-и-контентные-поля","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/extend/tailor-fields.md","filePath":"3.x/ru/extend/tailor-fields.md"}'),r={name:"3.x/ru/extend/tailor-fields.md"};function k(d,s,g,f,h,m){const o=t("pre-heading"),c=t("post-heading");return i(),u("div",null,[p(o),s[0]||(s[0]=n("h1",null,"Создание полей Tailor",-1)),p(c),s[1]||(s[1]=e(`<p>Вы можете создавать собственные контентные поля, определив файл определения поля и зарегистрировав его в файле регистрации плагина.</p><p>Классы определений контентных полей находятся внутри директории <strong>contentfields</strong> плагина. Имя внутренней директории совпадает с именем класса виджета в нижнем регистре. Контентные поля могут предоставлять ресурсы и частичные представления. Пример структуры директории выглядит так.</p><pre class="dir-container"><code><p>├── <code>contentfields</code>
|   ├── mycontentfield
|   |   ├── assets
|   |   └── partials
|   |       └── _column_content.php  <em>← Файл частичного представления</em>
|   └── MyContentField.php  <em>← Класс поля</em></p>
</code></pre><h3 id="определение-класса"><a href="#определение-класса" class="header-anchor">#</a> Определение класса</h3><p>Команда <code>create:contentfield</code> генерирует класс контентного поля. Первый аргумент указывает имя автора и плагина. Второй аргумент указывает имя класса контентного поля.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:contentfield Acme.Blog MyContentField
</code></pre></div><p>Класс контентного поля должен наследовать класс <code>Backend\\Classes\\FormWidgetBase</code>. Зарегистрированное контентное поле может использоваться в <a href="./../element/form-fields.html">полях форм Tailor</a> и чертежах. Класс определяет, как поле должно взаимодействовать с остальной системой. Например, <strong>plugins/acme/blog/contentfields/MyContentField.php</strong> со следующим содержимым.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>ContentFields</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Tailor<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ContentFieldBase</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Contracts<span class="token punctuation">\\</span>Element<span class="token punctuation">\\</span>FormElement</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Contracts<span class="token punctuation">\\</span>Element<span class="token punctuation">\\</span>ListElement</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Contracts<span class="token punctuation">\\</span>Element<span class="token punctuation">\\</span>FilterElement</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">MyContentField</span> <span class="token keyword">extends</span> <span class="token class-name">ContentFieldBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineConfig</span><span class="token punctuation">(</span><span class="token keyword type-hint">array</span> <span class="token variable">$config</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineFormField</span><span class="token punctuation">(</span><span class="token class-name type-declaration">FormElement</span> <span class="token variable">$form</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineListColumn</span><span class="token punctuation">(</span><span class="token class-name type-declaration">ListElement</span> <span class="token variable">$list</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineFilterScope</span><span class="token punctuation">(</span><span class="token class-name type-declaration">FilterElement</span> <span class="token variable">$filter</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendModelObject</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendDatabaseTable</span><span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="регистрация-контентного-поля"><a href="#регистрация-контентного-поля" class="header-anchor">#</a> Регистрация контентного поля</h3><p>Плагины должны регистрировать контентные поля, переопределяя метод <code>registerContentFields</code> в <a href="./extending.html">файле регистрации плагина</a>. Метод возвращает массив, содержащий класс виджета в ключах и короткий код виджета в значении. Пример:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerContentFields</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>ContentFields<span class="token punctuation">\\</span>MyContentField</span><span class="token operator">::</span><span class="token keyword">class</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;mycontentfield&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Короткий код используется при ссылке на поле в <a href="./introduction.html">шаблонах чертежей</a> и должен быть уникальным значением для предотвращения конфликтов с другими полями форм.</p><h2 id="обработка-конфигурации"><a href="#обработка-конфигурации" class="header-anchor">#</a> Обработка конфигурации</h2><p>Предположим, мы хотим включить элемент конфигурации поля под названием <code>secondaryTitle</code>. Сначала он определяется как свойство класса, а затем заполняется с помощью переопределения <code>defineConfig</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">MyContentField</span> <span class="token keyword">extends</span> <span class="token class-name">ContentFieldBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$secondaryTitle</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineConfig</span><span class="token punctuation">(</span><span class="token keyword type-hint">array</span> <span class="token variable">$config</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token keyword">isset</span><span class="token punctuation">(</span><span class="token variable">$config</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;secondaryTitle&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">secondaryTitle</span> <span class="token operator">=</span> <span class="token variable">$config</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;secondaryTitle&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Это становится доступным:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">my_field</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mycontentfield
    <span class="token key atrule">secondaryTitle</span><span class="token punctuation">:</span> Custom value goes here
</code></pre></div><h2 id="определение-элемента-панели-управления"><a href="#определение-элемента-панели-управления" class="header-anchor">#</a> Определение элемента панели управления</h2><p>Контентное поле может определять, как оно отображается в панели управления в виде поля формы, столбца списка и области фильтрации. Результирующий объект в каждом случае является объектом конфигурации с поддержкой цепочки методов или массива через метод <code>useConfig</code>. Подробнее см. в <a href="./../cms/tailor/content-fields.html">статье об определении контентных полей</a>.</p><h3 id="поле-формы"><a href="#поле-формы" class="header-anchor">#</a> Поле формы</h3><p>Метод <code>defineFormField</code> определяет, как контентное поле должно отображаться в форме. Каждое поле инициируется методом <code>addFormField</code>, который принимает имя поля и метку для отображения пользователю.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineFormField</span><span class="token punctuation">(</span><span class="token class-name type-declaration">FormElement</span> <span class="token variable">$form</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">addFormField</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">,</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">label</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">useConfig</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">config</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="столбец-списка"><a href="#столбец-списка" class="header-anchor">#</a> Столбец списка</h3><p>Метод <code>defineListColumn</code> определяет, как контентное поле должно отображаться в списке. Каждый столбец инициируется методом <code>defineListColumn</code>, который принимает имя поля и метку для отображения пользователю.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineListColumn</span><span class="token punctuation">(</span><span class="token class-name type-declaration">ListElement</span> <span class="token variable">$list</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$list</span><span class="token operator">-&gt;</span><span class="token function">defineColumn</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">,</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">label</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">displayAs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;switch&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="область-фильтрации"><a href="#область-фильтрации" class="header-anchor">#</a> Область фильтрации</h3><p>Метод <code>defineFilterScope</code> определяет, как контентное поле должно отображаться в фильтре. Каждая область инициируется методом <code>defineScope</code>, который принимает имя поля и метку для отображения пользователю.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineFilterScope</span><span class="token punctuation">(</span><span class="token class-name type-declaration">FilterElement</span> <span class="token variable">$filter</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$filter</span><span class="token operator">-&gt;</span><span class="token function">defineScope</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">,</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">label</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">displayAs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;switch&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="расширение-модели"><a href="#расширение-модели" class="header-anchor">#</a> Расширение модели</h2><p>Метод <code>extendModelObject</code> позволяет контентному полю расширять модель записи, например класс модели <code>Tailor\\Models\\EntryRecord</code>. Примером может быть преобразование поля в jsonable с помощью метода <code>addJsonable</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendModelObject</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addJsonable</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Другой подход — указать связь <code>belongsTo</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendModelObject</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">belongsTo</span><span class="token punctuation">[</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token class-name static-context">MyOtherModel</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="расширение-таблицы-базы-данных"><a href="#расширение-таблицы-базы-данных" class="header-anchor">#</a> Расширение таблицы базы данных</h2><p>Метод <code>extendDatabaseTable</code> используется для указания столбцов базы данных, необходимых для этого поля. Он использует упрощённую версию <a href="./../extend/database/structure.html">стандартной структуры миграции</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendDatabaseTable</span><span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">mediumText</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="полныи-пример-использования"><a href="#полныи-пример-использования" class="header-anchor">#</a> Полный пример использования</h2><p>Ниже приведён полный пример создания контентного поля для плагина October Test. Он добавляет тип <code>mycontentfield</code>, доступный для всех чертежей, как показано в примере ниже.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">mycontentfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Custom Content Field
        <span class="token key atrule">type</span><span class="token punctuation">:</span> mycontentfield
        <span class="token key atrule">firstColor</span><span class="token punctuation">:</span> red
        <span class="token key atrule">secondColor</span><span class="token punctuation">:</span> blue
</code></pre></div><p>Поле регистрируется в файле <strong>plugins/october/test/Plugin.php</strong> с помощью метода <code>registerContentFields</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerContentFields</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Test<span class="token punctuation">\\</span>ContentFields<span class="token punctuation">\\</span>MyContentField</span><span class="token operator">::</span><span class="token keyword">class</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;mycontentfield&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Класс поля создаётся в файле <strong>plugins/october/test/contentfields/MyContentField.php</strong> как PHP-класс. Он регистрируется как <a href="./../element/form/ui-partial.html">тип поля partial</a> и не включает столбец списка или область фильтрации для простоты. Вызов метода <code>addJsonable</code> гарантирует, что имя поля является <a href="./../extend/system/models.html">jsonable-свойством</a> и может храниться как массив. Столбец базы данных хранится как <a href="./../extend/database/structure.html">тип схемы базы данных</a> <code>mediumText</code> с модификатором <code>nullable</code>, допускающим пустые значения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">October<span class="token punctuation">\\</span>Test<span class="token punctuation">\\</span>ContentFields</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Tailor<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ContentFieldBase</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Contracts<span class="token punctuation">\\</span>Element<span class="token punctuation">\\</span>FormElement</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">MyContentField</span> <span class="token keyword">extends</span> <span class="token class-name">ContentFieldBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineFormField</span><span class="token punctuation">(</span><span class="token class-name type-declaration">FormElement</span> <span class="token variable">$form</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">addFormField</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">,</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">label</span><span class="token punctuation">)</span>
            <span class="token operator">-&gt;</span><span class="token function">useConfig</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">config</span><span class="token punctuation">)</span>
            <span class="token operator">-&gt;</span><span class="token function">displayAs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;partial&#39;</span><span class="token punctuation">)</span>
            <span class="token operator">-&gt;</span><span class="token function">path</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;$/october/test/contentfields/mycontentfield/partials/_field.php&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendModelObject</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addJsonable</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendDatabaseTable</span><span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">mediumText</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Файл <strong>plugins/october/test/contentfields/mycontentfield/partials/_field.php</strong> содержит содержимое частичного представления для рендеринга поля формы. Значения извлекаются и сохраняются как массив <code>[first_value =&gt; &#39;foo&#39;, second_value =&gt; &#39;bar&#39;]</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>row<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>col<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span>
            <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$field</span><span class="token operator">-&gt;</span><span class="token function">getName</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>[first_value]<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token function">e</span><span class="token punctuation">(</span><span class="token variable">$field</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;first_value&#39;</span><span class="token punctuation">]</span> <span class="token operator">??</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-control<span class="token punctuation">&quot;</span></span>
            <span class="token special-attr"><span class="token attr-name">style</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value css language-css"><span class="token property">color</span><span class="token punctuation">:</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$field</span><span class="token operator">-&gt;</span><span class="token property">firstColor</span> <span class="token operator">?</span><span class="token punctuation">:</span> <span class="token string single-quoted-string">&#39;red&#39;</span> <span class="token delimiter important">?&gt;</span></span></span><span class="token punctuation">&quot;</span></span></span>
        <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>col<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span>
            <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$field</span><span class="token operator">-&gt;</span><span class="token function">getName</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>[second_value]<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token function">e</span><span class="token punctuation">(</span><span class="token variable">$field</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;second_value&#39;</span><span class="token punctuation">]</span> <span class="token operator">??</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-control<span class="token punctuation">&quot;</span></span>
            <span class="token special-attr"><span class="token attr-name">style</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value css language-css"><span class="token property">color</span><span class="token punctuation">:</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$field</span><span class="token operator">-&gt;</span><span class="token property">secondColor</span> <span class="token operator">?</span><span class="token punctuation">:</span> <span class="token string single-quoted-string">&#39;blue&#39;</span> <span class="token delimiter important">?&gt;</span></span></span><span class="token punctuation">&quot;</span></span></span>
        <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="виджеты-форм-и-контентные-поля"><a href="#виджеты-форм-и-контентные-поля" class="header-anchor">#</a> Виджеты форм и контентные поля</h2><p>Часто возникает вопрос о различиях между виджетом формы и контентным полем, и что лучше в каких ситуациях. <a href="./forms/form-widgets.html">Виджеты форм</a> — это поля форм, используемые исключительно виджетом <code>Backend\\Widgets\\Form</code>, наряду с нативными <a href="./../element/form-fields.html">типами полей форм</a> (text, number, dropdown, partial и т.д.)</p><p>Контентные поля являются надмножеством полей форм, используемых исключительно Tailor, и идут дальше, включая также определение того, как это поле:</p><ul><li>отображается как <a href="./../element/list-columns.html">столбец списка</a></li><li>отображается как <a href="./../element/filter-scopes.html">область фильтрации</a></li><li>должно существовать в <a href="./database/structure.html">таблице базы данных</a></li><li>должно применять <a href="./services/validation.html">правила валидации</a></li><li>должно <a href="./system/models.html">расширять модель</a> (jsonable/связь)</li></ul><p>Если виджет формы определён без контентного поля, он всё равно может использоваться в Tailor по умолчанию и будет разрешён в тип контентного поля <code>Tailor\\ContentFields\\FallbackField</code>, который является базовым и регистрируется в базе данных как тип столбца TEXT.</p><p>Для надёжных решений лучше всего определять и виджет формы, и контентное поле. Это позволяет использовать поле <a href="./../extend/extending.html">в плагинах</a> и для контента в <a href="./../cms/tailor/blueprints.html">чертежах Tailor</a>. По следующим ссылкам представлен пример поля валюты, которое можно использовать везде.</p>`,51)),s[2]||(s[2]=n("ul",null,[n("li",null,[n("a",{href:"https://github.com/responsiv/currency-plugin/blob/master/formwidgets/Currency.php",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Виджет формы Currency"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])])]),n("li",null,[n("a",{href:"https://github.com/responsiv/currency-plugin/blob/master/contentfields/Currency.php",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Контентное поле Currency"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])])])],-1)),s[3]||(s[3]=e('<p>Вы можете заметить, что внутри контентного поля определение YAML задано в PHP. Синтаксис YAML в PHP довольно прост: имя PHP-метода — это имя свойства YAML, а значение передаётся как первый аргумент, по умолчанию — <code>true</code>. Единственное основное отличие — свойство <code>type</code> определяется методом <code>displayAs</code>.</p><p>Любое имя метода может быть вызвано и является частью цепочки на PHP-объекте. См. следующую таблицу для примеров преобразования YAML в PHP.</p><div class="table"><table tabindex="0"><thead><tr><th>YAML</th><th>PHP</th></tr></thead><tbody><tr><td><code>autoFocus: true</code></td><td><code>-&gt;autoFocus()</code></td></tr><tr><td><code>label: my field</code></td><td><code>-&gt;label(&#39;my field&#39;)</code></td></tr><tr><td><code>type: partial</code></td><td><code>-&gt;displayAs(&#39;partial&#39;)</code></td></tr></tbody></table></div><div class="custom-block tip"><p>Вы также можете передать всю желаемую YAML-конфигурацию как массив с помощью <code>-&gt;useConfig([...])</code>.</p></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../cms/tailor/content-fields.html">Контентные поля Tailor</a></li></ul></div>',6))])}const b=l(r,[["render",k]]);export{v as __pageData,b as default};
